use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let obj = input.as_object().unwrap();
    let n = obj["n"].as_i64().unwrap();
    let start = obj["start"].as_i64().unwrap();
    let target = obj["target"].as_i64().unwrap();
    let edges = obj["edges"].as_array().unwrap();

    let mut graph = vec![vec![]; n as usize];
    for edge in edges {
        let edge = edge.as_array().unwrap();
        let from = edge[0].as_i64().unwrap() as usize;
        let to = edge[1].as_i64().unwrap() as usize;
        graph[from].push(to);
    }

    let mut distances = vec![i64::MAX; n as usize];
    distances[start as usize] = 0;

    let mut queue = vec![start];
    while let Some(node) = queue.pop() {
        for &neighbor in &graph[node] {
            if distances[node] + 1 < distances[neighbor] {
                distances[neighbor] = distances[node] + 1;
                queue.push(neighbor);
            }
        }
    }

    if distances[target as usize] == i64::MAX {
        json!(-1)
    } else {
        json!(distances[target as usize])
    }
}
